source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    runs = []
    source_rows = set()
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            if c - start >= 2:
                runs.append((r, start, row[start:c]))
                source_rows.add(r)
    for r, row in enumerate(grid):
        if r in source_rows:
            continue
        for c, value in enumerate(row):
            if value == 0:
                continue
            candidates = [(sr, start, seq) for sr, start, seq in runs if value in seq]
            if not candidates:
                continue
            _, _, seq = candidates[0]
            start_col = c - seq.index(value)
            for offset, color in enumerate(seq):
                cc = start_col + offset
                if 0 <= cc < w:
                    out[r][cc] = color
    return out
'''
